const data = $input.first().json;

const workflowName = data.workflow?.name || 'Unknown workflow';
const nodeName = data.execution?.lastNodeExecuted || 'Unknown node';
const errorMessage = data.execution?.error?.message || 'Unknown error';
const executionUrl = data.execution?.url || '';
const time = new Date().toISOString();

const alertText = `🚨 ERREUR

Workflow: ${workflowName}
Node: ${nodeName}
Erreur: ${errorMessage}
Heure: ${time}

${executionUrl ? 'Détails: ' + executionUrl : ''}`;

return [{
  json: {
    workflow_name: workflowName,
    node_name: nodeName,
    error_message: errorMessage,
    execution_url: executionUrl,
    time: time,
    alert_text: alertText
  }
}];
